import "errors"

// maxInt64 is the maximum value of a signed 64-bit integer.
const maxInt64 = int64(9223372036854775807)

// errSyntax is returned when the input is not a valid hexadecimal string.
var errSyntax = errors.New("invalid syntax: not a valid hexadecimal string")

// errRange is returned when the hexadecimal value exceeds the range of int64.
var errRange = errors.New("value out of range: exceeds int64")

// hexDigitValue returns the numeric value of a hexadecimal character,
// or -1 if the character is not a valid hexadecimal digit.
func hexDigitValue(c byte) int {
    switch {
    case c >= '0' && c <= '9':
        return int(c - '0')
    case c >= 'a' && c <= 'f':
        return int(c - 'a' + 10)
    case c >= 'A' && c <= 'F':
        return int(c - 'A' + 10)
    }
    return -1
}

// ParseHex converts a hexadecimal string to its decimal equivalent.
// It returns a syntax error for invalid input and a range error when the
// value does not fit in an int64.
func ParseHex(in string) (int64, error) {
    if in == "" {
        return 0, errSyntax
    }

    var result int64
    for i := 0; i < len(in); i++ {
        d := hexDigitValue(in[i])
        if d < 0 {
            return 0, errSyntax
