package hexadecimal

// maxInt64 is the largest value representable by a signed 64-bit integer.
const maxInt64 = int64(9223372036854775807)

// hexError is a minimal error that carries a classification so callers can
// distinguish the two failure modes without inspecting the message text.
type hexError struct {
	kind string // "syntax" or "range"
}

func (e *hexError) Error() string {
	if e.kind == "syntax" {
		return "invalid syntax: not a valid hexadecimal string"
	}
	return "value out of range: exceeds int64"
}

var (
	errSyntax = &hexError{kind: "syntax"}
	errRange  = &hexError{kind: "range"}
)

// hexDigitValue returns the numeric value of a hexadecimal digit, or -1 if
// the byte is not a valid hexadecimal digit.
func hexDigitValue(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent. The conversion is done from first principles: each character
// is mapped to its digit value and accumulated in base 16.
//
// It returns errSyntax for empty or non-hexadecimal input and errRange when
// the value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errSyntax
	}

	var result int64
	for i := 0; i < len(in); i++ {
		d := hexDigitValue(in[i])
		if d < 0 {
			return 0, errSyntax
		}
		// Detect overflow before it happens: if result*16+d would exceed
		// maxInt64, the value is out of range.
		if result > (maxInt64-int64(d))/16 {
			return 0, errRange
		}
		result = result*16 + int64(d)
	}
	return result, nil
}

// HandleErrors calls ParseHex on each input and returns a matching list
// classifying each result as "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		default:
			if he, ok := err.(*hexError); ok {
				results[i] = he.kind
			} else {
				results[i] = "syntax"
			}
		}
	}
	return results
}
